 static Material Mat(string name,Color color){string path="Assets/TruckWallball/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Smoothness",.35f);return m;}
 static PhysicsMaterial Contact(string name,float bounce,float friction){string path="Assets/TruckWallball/Materials/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(m==null){m=new PhysicsMaterial(name);AssetDatabase.CreateAsset(m,path);}m.bounciness=bounce;m.dynamicFriction=m.staticFriction=friction;m.bounceCombine=PhysicsMaterialCombine.Maximum;m.frictionCombine=PhysicsMaterialCombine.Minimum;EditorUtility.SetDirty(m);return m;}
 static GameObject Box(string name,Vector3 p,Vector3 s,Material paint,PhysicsMaterial physics=null){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=paint;if(physics==null)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());else g.GetComponent<Collider>().sharedMaterial=physics;return g;}
 static TextMesh Label(string name,string text,Vector3 p,float size,Color color){var g=new GameObject(name);g.transform.position=p;var t=g.AddComponent<TextMesh>();t.text=text;t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.fontSize=64;t.characterSize=size;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.color=color;g.GetComponent<Renderer>().sharedMaterial=t.font.material;return t;}
