 static void CreateWheels(WallballTruck truck){truck.gameObject.layer=2;var friction=AssetDatabase.LoadAssetAtPath<FrictionPreset>("Assets/NWH/WheelController/Resources/Wheel Controller 3D/Defaults/DefaultFrictionPreset.asset");truck.wheels=new WheelController[4];for(int i=0;i<4;i++){var g=new GameObject("NWH court wheel "+i);g.layer=2;g.transform.SetParent(truck.transform,false);g.transform.localPosition=new Vector3(i%2==0?-.38f:.38f,0,i<2?.65f:-.65f);var w=g.AddComponent<WheelController>();w.wheel.radius=.2f;w.wheel.width=.12f;w.wheel.mass=.4f;w.spring.maxLength=.08f;w.spring.maxForce=60;w.damper.bumpRate=w.damper.reboundRate=90;w.rollingResistanceTorque=.015f;w.FrictionPreset=friction;w.frictionSubsteps=10;w.forceApplicationPointDistance=.035f;w.layerMask=1<<0;truck.wheels[i]=w;}}
