 public static void Validate(){WallballFixtures.Run();var scene=EditorSceneManager.OpenScene(Scene);foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Wallball missing script "+t.name);var m=UnityEngine.Object.FindAnyObjectByType<WallballMatch>();if(m==null||m.trucks.Length!=8||m.agents.Length!=8||m.floor==null||m.wall==null||m.ball==null||m.menus.names.Length!=8||m.feedback.clips.Length!=8||m.feedback.clips.Any(c=>c==null)||m.trucks.Any(t=>t.engine.clip==null))throw new Exception("Wallball references incomplete");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1||UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length!=1)throw new Exception("Wallball event/listener count");if(m.trucks.Any(t=>t.wheels.Length!=4||t.wheels.Any(w=>w.layerMask.value!=1)||t.GetComponentsInChildren<Collider>().Length!=1))throw new Exception("Wallball truck collider model");Debug.Log("WB_SAVED_SCENE_VALIDATED");}
}
